from z3 import *

# Worlds
worlds = [
    "s0_0","s0_1","s1_0","s1_1","s2_0","s2_1","s3_0","s3_1",
    "s4_0","s4_1","s5_0","s5_1","s6_0","s6_1","s7_0","s7_1",
    "s8_0","s8_1","s9_0","s9_1","s10_0","s10_1"
]
initial_world = "s0_0"

# Accessibility relation (successor map)
edges = {
    ("s0_0","s1_0"),("s0_0","s1_1"),("s0_1","s1_1"),("s0_1","s1_0"),
    ("s1_0","s2_0"),("s1_0","s2_1"),("s1_1","s2_1"),("s1_1","s2_0"),
