    ("s4_0","s5_0"),("s4_0","s5_1"),("s4_1","s5_1"),("s4_1","s5_0"),
    ("s5_0","s6_0"),("s5_0","s6_1"),("s5_1","s6_1"),("s5_1","s6_0"),
