    ("s9_0","s10_0"),("s9_0","s10_1"),("s9_1","s10_1"),("s9_1","s10_0"),
    ("s10_0","s10_1")
}
succ = {w: [] for w in worlds}
for (u,v) in edges:
    succ[u].append(v)
# Ensure every world key exists (already initialized)

# Atomic propositions valuation sets
bottom_set = {"s0_0","s1_0","s2_0","s3_0","s4_0","s5_0","s6_0","s7_0","s8_0","s9_0","s10_0"}
top_set    = {"s0_1","s1_1","s2_1","s3_1","s4_1","s5_1","s6_1","s7_1","s8_1","s9_1","s10_1"}
goal_set   = {"s10_1"}
final_column_set = {"s10_0","s10_1"}
can_vertical_up_set = {"s10_0"}
col_sets = {
    0: {"s0_0","s0_1"},
    1: {"s1_0","s1_1"},
    2: {"s2_0","s2_1"},
    3: {"s3_0","s3_1"},
    4: {"s4_0","s4_1"},
    5: {"s5_0","s5_1"},
    6: {"s6_0","s6_1"},
    7: {"s7_0","s7_1"},
    8: {"s8_0","s8_1"},
    9: {"s9_0","s9_1"},
    10: {"s10_0","s10_1"}
}

def P_bottom(w): return BoolVal(w in bottom_set)
def P_top(w): return BoolVal(w in top_set)
def P_goal(w): return BoolVal(w in goal_set)
def P_final_column(w): return BoolVal(w in final_column_set)
def P_can_vertical_up(w): return BoolVal(w in can_vertical_up_set)
def P_col(i, w): return BoolVal(w in col_sets[i])

# Z3 solver
s = Solver()

# Unroll EF(goal) with bounded dynamic programming up to K steps
K = 21  # exceeds max simple path length here; sufficient for EF
EF_reach = {}
for k in range(K+1):
    EF_reach[k] = {}
    for w in worlds:
        EF_reach[k][w] = Bool(f"EF_reach_k{k}_{w}")

# Base case: length 0 (already at goal)
for w in worlds:
    s.add(EF_reach[0][w] == P_goal(w))

# Induction: length <= k+1
for k in range(K):
    for w in worlds:
        succ_reach = [EF_reach[k][v] for v in succ[w]]
        s.add(EF_reach[k+1][w] == Or(EF_reach[k][w], Or(succ_reach)))

# EF(goal) at a world is EF_reach[K][w]
def EF_goal_at(w):
    return EF_reach[K][w]

# AX over a column predicate: AX col_{j} at world w
def AX_col(j, w):
    return And([P_col(j, v) for v in succ[w]])

# EX goal at world w
def EX_goal_at(w):
    return Or([P_goal(v) for v in succ[w]])

# Encode AG(col_i -> AX col_{i+1}) for i = 0..9
AG_col_axioms = {}
for i in range(10):
    AG_col_axioms[i] = {}
    # create variables first
    for w in worlds:
        AG_col_axioms[i][w] = Bool(f"AG_col{i}_imp_AX_col{i+1}_{w}")
    # add defining equations
    for w in worlds:
        chi = Implies(P_col(i, w), AX_col(i+1, w))
        s.add(AG_col_axioms[i][w] == And(chi, And([AG_col_axioms[i][v] for v in succ[w]])))

# Encode AG(final_column & bottom -> EX goal)
AG_final = {w: Bool(f"AG_final_implies_EXgoal_{w}") for w in worlds}
for w in worlds:
    antecedent = And(P_final_column(w), P_bottom(w))
    chiF = Implies(antecedent, EX_goal_at(w))
    s.add(AG_final[w] == And(chiF, And([AG_final[v] for v in succ[w]])))

# Assert the desired properties:
# 1) EF(goal) at initial world
s.add(EF_goal_at(initial_world))

# 2) Global invariants AG(...)
for i in range(10):
    for w in worlds:
        s.add(AG_col_axioms[i][w])
for w in worlds:
    s.add(AG_final[w])

# Solve
res = s.check()
print(f"Solver result: {res}")

if res == sat:
    m = s.model()
    # Report EF(goal) at initial and a witness path
    print(f"EF(goal) holds at initial world {initial_world}: {m.evaluate(EF_goal_at(initial_world))}")

    # Extract a witness path to goal using the unrolled reachability info
    def witness_path(start, Kmax):
        path = [start]
        cur = start
        for step in range(Kmax+1):
            if cur in goal_set:
                break
            # choose a successor that still can reach goal within remaining steps
            found = False
            remaining = Kmax - step - 1
            for v in succ[cur]:
                if remaining >= 0 and is_true(m.evaluate(EF_reach[remaining][v])):
                    path.append(v)
                    cur = v
                    found = True
                    break
            if not found:
                # No successor found; stop
                break
        return path

    path = witness_path(initial_world, K)
    print("One EF(goal) witness path from initial:")
    print(" -> ".join(path))

    # Verify AG properties
    for i in range(10):
        all_ok = all(is_true(m.evaluate(AG_col_axioms[i][w])) for w in worlds)
        print(f"AG(col{i} -> AX col{i+1}) holds at all worlds: {all_ok}")
    all_ok_final = all(is_true(m.evaluate(AG_final[w])) for w in worlds)
    print(f"AG(final_column & bottom -> EX goal) holds at all worlds: {all_ok_final}")

    # Optional: show which worlds satisfy EF(goal)
    ef_states = [w for w in worlds if is_true(m.evaluate(EF_goal_at(w)))]
    print("Worlds satisfying EF(goal):", ef_states)
else:
    if res == unknown:
        print("Reason for unknown:", s.reason_unknown())
    # When unsat or unknown, no model to print

